# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
JW=[['更早来源有争议：可能接拉丁 jocus 及中世纪拉丁 jocale，也有 gaudium“喜悦”等解释','不能确定只属于“玩笑”这一条词源'],['古法语 jouel／盎格鲁法语 juel','珍贵装饰品、礼物、宝石'],['英语 jewel','宝石、珍贵饰物；比喻珍贵的人或物']]
JR=JW[:-1]+[['古法语 juelerye → 中古英语 juelrye','珠宝首饰、珠宝工艺'],['现代 jewelry／jewellery','首饰统称；也能按 jewel + -ery 理解其结构']]
JE=JW[:-1]+[['古法语 juelier／盎格鲁法语 jueler → 英语 jeweler／jeweller','制作、销售或修理珠宝首饰的人']]
WB=[
E('jewel','英 /ˈdʒuːəl/；美 /ˈdʒuːəl/，也常读成 /dʒuːl/','宝石；珍贵饰物；珍宝般的人或事物','一件小东西，因为美丽、稀有或特别重要，被人当作珍宝。','可靠的近层来源是法语 jouel／juel。更早接 jocus“游戏、消遣”的路线是一种解释，不是定论。',JW,'jewel 可以是宝石，也可以是镶有宝石的贵重饰物。比喻说 a jewel of a place，是赞美某处格外美好、珍贵。即使采用“让人喜爱的玩物”这条记忆线，也不能把 jewel 硬解释成 joke 直接变出来的词。','a precious jewel；a jewel of a town；the jewels in a collection。','gem 常着重宝石本身；jewelry／jewellery 是首饰统称。一般说 a piece of jewelry，不说 a jewelry。',('A blue jewel was set in the ring.','戒指上镶着一颗蓝色宝石。'),('The small museum is a jewel of the town.','这座小博物馆是镇上的一颗明珠。'),sources=['https://www.etymonline.com/word/jewel','https://en.wiktionary.org/wiki/jewel']),
E('jewelry','美 /ˈdʒuːəlri/，常简化为 /ˈdʒuːlri/','珠宝首饰；首饰〔美式常用拼写〕','把戒指、项链、耳环等佩戴的装饰品放在同一个类别里。','与 jewel 同族，历史有古法语 juelerye；现代也能按 jewel + -ery 或 jeweler + -y 分析。',JR,'jewelry 是首饰的集合称呼，通常不可数。它不要求每一件都镶着真正的宝石，塑料饰品、金属饰品也可能属于 jewelry。真正要数的是 pieces of jewelry，或直接说 rings、necklaces 等具体物件。','wear jewelry；a piece of jewelry；a jewelry store；costume jewelry。','jewelry 与 jewellery 主要是美式、英式拼写差异；jewels 常更突出宝石或贵重饰物，范围并不完全一样。',('She rarely wears jewelry at work.','她上班时很少戴首饰。'),('The bracelet was her favorite piece of jewelry.','那只手镯是她最喜欢的一件首饰。'),sources=['https://www.etymonline.com/word/jewelry','https://en.wiktionary.org/wiki/jewellery']),
E('jewellery','英 /ˈdʒuːəlri/','珠宝首饰；首饰〔英式常用拼写〕','看到多出的字母，意思仍是人们佩戴的那一类装饰品。','与 jewelry 同源；古法语及中古英语已有对应首饰集合词，现代英式常用较长拼写 jewellery。',JR+[['英式常见拼写 jewellery','首饰统称']],'jewellery 常见于英国商店、网站和日常写作。它通常不可数，a jewellery shop 是首饰店，two pieces of jewellery 是两件首饰。拼写更长，不代表首饰更贵，也不代表另一个专业分类。','a jewellery shop；handmade jewellery；a jewellery box。','jewellery 是物品统称，jeweller 是制作、出售或修理首饰的人，也常借指其商店。',('She keeps her jewellery in a small wooden box.','她把首饰放在一个小木盒里。'),('The shop sells handmade silver jewellery.','这家店出售手工银饰。'),sources=['https://en.wiktionary.org/wiki/jewellery','https://www.etymonline.com/word/jewelry']),
E('jeweler','美 /ˈdʒuːələr/，也常读 /ˈdʒuːlər/','珠宝商；首饰工匠〔美式常用拼写〕','不只是佩戴珠宝的人，而是做、修或卖珠宝首饰的人。','现代可联系 jewel + -er；历史上英语也借入了法语表示珠宝从业者的形式。',JE,'jeweler 可以是做首饰、修首饰的工匠，也可以是经营珠宝首饰的商人。具体能力因人和店而异；需要修戒指时去 a jeweler，重点是相关服务，不只是珠宝鉴定这一件事。','a local jeweler；take a ring to a jeweler；a skilled jeweler。','jeweler 是职业或经营者；jewelry 是首饰。gemologist 专门涉及宝石学或宝石鉴定，不能与所有 jeweler 自动画等号。',('The jeweler repaired the clasp on my necklace.','首饰工匠修好了我项链上的扣子。'),('We asked a local jeweler to resize the ring.','我们请当地的一位珠宝商调整戒指尺寸。'),sources=['https://www.etymonline.com/word/jeweler','https://www.merriam-webster.com/dictionary/jeweler']),
E('jeweller','英 /ˈdʒuːələ/，也可读 /ˈdʒuːlə/','珠宝商；首饰工匠〔英式常用拼写〕','谈的是提供珠宝制作、销售或修理服务的人。','与 jeweler 同源；英式常保留双写 l。词形可联系 jewel，但历史也有独立法语职业名词的借入。',JE+[['英式常见拼写 jeweller','珠宝首饰从业者；所有格也常指店铺']],'a jeweller 是珠宝商或首饰工匠。英式常说 at the jeweller’s，意思是“在珠宝店”，后面省略 shop。这种所有格指店铺的用法也出现在 the baker’s、the butcher’s 中。','a jeweller’s shop；at the jeweller’s；a master jeweller。','jeweller’s 可以指一家店；jewellers 是复数形式。看到结尾 s，要留意有没有所有格撇号以及整句语境。',('The jeweller showed us several simple rings.','珠宝商给我们看了几款简洁的戒指。'),('Her necklace is still at the jeweller’s for repair.','她的项链还留在珠宝店维修。'),sources=['https://www.merriam-webster.com/dictionary/jeweler','https://www.etymonline.com/word/jeweler']),
]
